for k in required:
    if k not in assign:
        # Missing slot
        return (False, None)
try:
    s = int(assign['num_vertices'])
    t = int(assign['num_moves'])
    a = int(assign['prob_num'])
    b = int(assign['prob_den'])
except Exception:
    # Non-integer values provided
    return (False, None)

# Domain constraints
if s < 5 or s % 2 == 0:
    # Must be an odd cycle length >= 5
    return (False, None)
if t <= 0:
    # Must have positive number of moves
    return (False, None)
if not (1 <= a < b):
    # Probability must be strictly between 0 and 1
    return (False, None)
if 2 * a == b:
    # Exclude p = 1/2 to avoid symmetry/trivialities requirement
    return (False, None)

# Compute residue class solutions for 2R ≡ t (mod s)
inv2 = (s + 1) // 2  # inverse of 2 modulo s for odd s
R0 = (inv2 * (t % s)) % s
Rlist = list(range(R0, t + 1, s))
if len(Rlist) == 0:
    # No valid paths returning to origin; trivial probability 0 not allowed
    return (False, None)
if len(Rlist) < 2 and t > s:
    # Enforce nontrivial sum (at least two terms) when t is reasonably large
    return (False, None)

# Compute probability exactly as a reduced Fraction
prob = Fraction(0, 1)
for r in Rlist:
    prob += Fraction(math.comb(t, r) * (a ** r) * ((b - a) ** (t - r)), b ** t)

if prob == 0 or prob == 1:
    # Trivial probabilities disallowed
    return (False, None)

# Final answer: m + n for reduced fraction m/n
answer = prob.numerator + prob.denominator
return (True, int(answer))


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

